import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] v = new int[10];
        for (int i=0; i<k; i++) {
            v[sc.nextInt()] = 1;
        }
        int[] comb = {1};
        int powerCount = n/2;
        while (powerCount > 0) {
            if ((powerCount & 1) == 1) {
                comb = polynomialMultiply(comb, v, 998244353);
            }
            v = polynomialMultiply(v, v, 998244353);
            powerCount >>= 1;
        }
        long totalSum = 0;
        for (int val : comb) {
            totalSum = (totalSum + (long) val * val) % 998244353;
        }
        System.out.println(totalSum);
    }

    static int[] polynomialMultiply(int[] p1, int[] p2, int mod) {
        int size = Math.max(2, Integer.highestOneBit(p1.length + p2.length -1)<<1);
        double[] aReal = new double[size];
        double[] aImag = new double[size];
        for (int i=0; i<p1.length; i++) {
            int x = ((p1[i] % mod) + mod) % mod;
            aReal[i] = x & ((1 << 15) - 1);
            aImag[i] = x >> 15;
        }
        fftTransform(aReal, aImag, false);
        double[] bReal = new double[size];
        double[] bImag = new double[size];
        if (p1 == p2) {
            System.arraycopy(aReal, 0, bReal, 0, size);
            System.arraycopy(aImag, 0, bImag, 0, size);
        } else {
            for (int i=0; i<p2.length; i++) {
                int x = ((p2[i] % mod) + mod) % mod;
                bReal[i]= x & ((1<<15)-1);
                bImag[i]= x>>15;
            }
            fftTransform(bReal, bImag, false);
        }

        double[] faReal = new double[size];
        double[] faImag = new double[size];
        double[] fbReal = new double[size];
        double[] fbImag = new double[size];

        double cof= 0.25/size;
        for (int i=0; i<size; i++) {
            int j= (size - i) & (size - 1);
            double a1r = (aReal[i] + aReal[j]);
            double a1i = (aImag[i] - aImag[j]);
            double a2r = (aImag[i] + aImag[j]);
            double a2i = (aReal[j] - aReal[i]);

            double b1r= (bReal[i]+bReal[j]) * cof;
            double b1i= (bImag[i]-bImag[j]) * cof;
            double b2r= (bImag[i]+bImag[j]) * cof;
            double b2i= (bReal[j]-bReal[i]) * cof;

            faReal[i]= a1r*b1r - a1i*b1i - a2r*b2i -a2i*b2r;
            faImag[i]= a1r*b1i + a1i*b1r + a2r*b2r - a2i*b2i;

            fbReal[i]= a1r*b2r - a1i*b2i + a2r*b1r - a2i*b1i;
            fbImag[i]= a1r*b2i + a1i*b2r + a2r*b1i + a2i*b1r;
        }

        fftTransform(faReal, faImag, true);
        fftTransform(fbReal, fbImag, true);

        int[] res= new int[size];
        for (int i=0; i< size; i++) {
            long aa= Math.round(faReal[i]);
            long bb= Math.round(fbReal[i]);
            long cc= Math.round(faImag[i]);
            res[i]= (int)((aa + (bb % mod)<<15) + ((cc % mod)<<30)) % mod;
        }
        return res;
    }

    static void fftTransform(double[] real, double[] imag, boolean invert) {
        int n= real.length;
        for (int i=1, j=0; i<n; i++) {
            int bit= n>>1;
            for (; (j & bit) !=0; bit>>=1) {
                j&= ~bit;
            }
            j|= bit;
            if (i<j) {
                double tmp= real[i];
                real[i]= real[j];
                real[j]= tmp;
                tmp= imag[i];
                imag[i]= imag[j];
                imag[j]= tmp;
            }
        }
        for (int len=2; len<=n; len<<=1) {
            double angle= 2*Math.PI/len * (invert ? -1:1);
            double wlenCos= Math.cos(angle);
            double wlenSin= Math.sin(angle);
            for (int i=0; i<n; i+=len) {
                double wCos=1, wSin=0;
                for (int j=0; j<len/2; j++) {
                    double u= real[i+j], v= real[i+j+len/2] * wCos + imag[i+j+len/2] * wSin;
                    real[i + j]= u+v;
                    real[i + j + len/2]= u-v;
                    double tempW= wCos * wlenCos - wSin * wlenSin;
                    wSin= wSin*wlenCos + wCos*wlenSin;
                    wCos= tempW;
                }
            }
        }
        if (invert) {
            for (int i=0; i<n; i++) {
                real[i]/= n;
            }
        }
    }
}
